663	
664	/* ---------- Factory function ---------- */
665	template <>
666	Status CreateOperation(const infer::AddcustomParam &opParam, Operation **operation)
667	{
668	    if (operation == nullptr) return ERROR_INVALID_PARAM;
669	    OP_PARAM_RSV_CHECK(opParam);
670	
671	    *operation = new (std::nothrow) AddcustomOperation(opParam);
672	    if (*operation == nullptr) {
673	        ATB_LOG(ERROR) << "failed to new AddcustomOperation";
674	        return ERROR_INTERNAL_ERROR;
