692	                                          SVector<TensorDesc> &outTensorDescs) const
693	{
694	    outTensorDescs[0] = inTensorDescs[0]; // The output is identical to input 0.
695	    return NO_ERROR;
696	}
697	
698	/* ---------- Validation ---------- */
699	Status AddcustomOperation::InferShapeCheckImpl(const SVector<TensorDesc> &inTensorDescs) const
700	{
701	    return InTensorDescsCheck(inTensorDescs);
702	}
703	
704	Status AddcustomOperation::SetupCheckImpl(const SVector<Tensor> &inTensors, const SVector<Tensor> &outTensors) const
705	{
706	    SVector<TensorDesc> inTensorDescs;
707	    OperationUtil::InTensorsToInTensorDescs(inTensors, inTensorDescs);
708	    ATB_LOG(DEBUG) << "outTensors size:" << outTensors.size();
709	
710	    return InTensorDescsCheck(inTensorDescs);
711	}
712	
713	/* ---------- Runner creation ---------- */
714	std::shared_ptr<Runner> AddcustomOperation::CreateRunner(Context &context) const
715	{
716	    (void)context;
717	    return std::make_shared<AddcustomOpsRunner>(param_);
718	}
719	
720	/* ---------- Parameter JSON ---------- */
721	nlohmann::json AddcustomOperation::GetParamJson() const { return OpParamToJson(param_); }
722	
723	/* ---------- Specific validation ---------- */
724	Status AddcustomOperation::InTensorDescsCheck(const SVector<TensorDesc> &inTensorDescs) const
725	{
726	    // Count
727	    if (inTensorDescs.size() != 2) {
728	        ATB_LOG(ERROR) << GetLogPrefix() << "Addcustom expect 2 inputs";
729	        return ERROR_INVALID_PARAM;
730	    }
731	
732	    // shape
733	    if (inTensorDescs[0].shape.dimNum != inTensorDescs[1].shape.dimNum) {
734	        ATB_LOG(ERROR) << GetLogPrefix() << "Addcustom inputs must have same shape";
735	        return ERROR_INVALID_PARAM;
736	    }
737	    return NO_ERROR;
738	}
