7	 * INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.
8	 * See LICENSE in the root of the software repository for the full text of the License.
9	 */
10	#include "kernel_operator.h"
11	#include "kernels/utils/kernel/kernel_utils.h"
12	#include "kernels/elewise/quant/quant_tiling/tiling_data.h"
13	static constexpr int32_t BUFFER_NUM = 1; // tensor num for each queue
14	static constexpr uint32_t DATA_BYTE = 2;
15	static constexpr uint32_t BLOCK_NUMEL = 16;
16	
17	using AscendC::HardEvent;
18	
19	class KernelQuantization {
20	public:
21	    __aicore__ inline KernelQuantization() {}
22	
23	    __aicore__ inline uint32_t CEIL_DIV(uint32_t x, uint32_t y)
24	    {
25	        if (y == 0) {
26	            return UINT32_MAX;
27	        }
28	        return (x + y - 1) / y;
29	    }
30	
31	    __aicore__ inline uint32_t ROUND_UP(uint32_t x) { return (x + BLOCK_NUMEL - 1) / BLOCK_NUMEL * BLOCK_NUMEL; }
32	
33	    __aicore__ inline uint32_t MIN(uint32_t x, uint32_t y) { return x < y ? x : y; }
34	    __aicore__ inline uint32_t MAX(uint32_t x, uint32_t y) { return x > y ? x : y; }
35	
36	    __aicore__ inline void Init(__gm__ uint8_t *x, __gm__ uint8_t *z, uint32_t num_core_, uint32_t num_Last_dim_,
37	                                uint32_t num_first_dim_, uint32_t nl_first_dim_per_core_,
38	                                uint32_t l_first_dim_per_core_, uint32_t first_dim_per_times_, uint32_t scale_,
39	                                uint32_t offset_, int32_t quant_min_)
40	    {
41	        // 一次搬入多行
42	        num_core = num_core_;
43	        num_last_dim = num_Last_dim_;
44	        num_first_dim = num_first_dim_;
45	        nl_first_dim_per_core = nl_first_dim_per_core_;
46	        l_first_dim_per_core = l_first_dim_per_core_;
47	        first_dim_per_times = first_dim_per_times_;
48	        quant_min = static_cast<half>(quant_min_);
49	
50	        input_scale = *reinterpret_cast<float *>(&scale_);
51	        input_offset = *reinterpret_cast<int32_t *>(&offset_);
52	
53	        if (AscendC::GetBlockIdx() != num_core - 1) {
54	            row_work = nl_first_dim_per_core;
55	            row_step = first_dim_per_times;
56	        } else {
57	            row_work = l_first_dim_per_core;
58	            row_step = MIN(first_dim_per_times, row_work);
59	        }
60	        row_tail_ = (row_work % first_dim_per_times == 0) ? first_dim_per_times : (row_work % first_dim_per_times);
61	        gm_offset_ = nl_first_dim_per_core * num_last_dim;
62	        x_gm.SetGlobalBuffer((__gm__ half *)x + AscendC::GetBlockIdx() * gm_offset_);
63	        z_gm.SetGlobalBuffer((__gm__ int8_t *)z + AscendC::GetBlockIdx() * gm_offset_);
64	        pipe.InitBuffer(x_que, BUFFER_NUM, row_step * ROUND_UP(num_last_dim) * DATA_BYTE);
65	        pipe.InitBuffer(z_que, BUFFER_NUM, row_step * ROUND_UP(num_last_dim) * sizeof(int8_t));
66	    }
67	
68	    __aicore__ inline void Process()
69	    {
70	        uint32_t move_cnt = CEIL_DIV(row_work, row_step); // 一个核需要做多少次
71	        for (uint64_t i = 0; i < move_cnt; ++i) {
72	            if (i < move_cnt - 1) {
73	                CopyIn(i, row_step * num_last_dim);
74	
75	                AscendC::SetFlag<HardEvent::MTE2_V>(EVENT_ID0);
76	                AscendC::WaitFlag<HardEvent::MTE2_V>(EVENT_ID0);
77	
78	                Compute(row_step);
79	
80	                AscendC::SetFlag<HardEvent::V_MTE2>(EVENT_ID0);
81	                AscendC::WaitFlag<HardEvent::V_MTE2>(EVENT_ID0);
82	
83	                CopyOut(i, row_step * num_last_dim);
84	            } else {
85	                CopyIn(i, row_tail_ * num_last_dim);
86	
87	                AscendC::SetFlag<HardEvent::MTE2_V>(EVENT_ID1);
88	                AscendC::WaitFlag<HardEvent::MTE2_V>(EVENT_ID1);
89	
90	                Compute(row_tail_);
91	
92	                AscendC::SetFlag<HardEvent::V_MTE2>(EVENT_ID1);
93	                AscendC::WaitFlag<HardEvent::V_MTE2>(EVENT_ID1);
94	
95	                CopyOut(i, row_tail_ * num_last_dim);
96	            }
97	        }
98	    }
99	
100	private:
101	    __aicore__ inline void CopyIn(uint64_t proc_id, int32_t size)
102	    {
103	        // alloc tensor from queue memory
104	        AscendC::LocalTensor<half> x_local = x_que.AllocTensor<half>();
105	        uint64_t offset = proc_id * row_step * num_last_dim;
106	        DataCopy(x_local, x_gm[offset], size);
107	        x_que.EnQue(x_local);
108	    }
109	
110	    __aicore__ inline void Compute(int32_t nums)
111	    {
112	        AscendC::LocalTensor<half> x_local = x_que.DeQue<half>();
113	        AscendC::LocalTensor<int8_t> z_local = z_que.AllocTensor<int8_t>();
114	
115	        for (int32_t rid = 0; rid < nums; ++rid) {
116	            AscendC::PipeBarrier<PIPE_V>();
117	            Muls(x_local[rid * num_last_dim], x_local[rid * num_last_dim], static_cast<half>(input_scale),
118	                 num_last_dim);
119	            AscendC::PipeBarrier<PIPE_V>();
120	            Adds(x_local[rid * num_last_dim], x_local[rid * num_last_dim], static_cast<half>(input_offset),
121	                 num_last_dim);
122	            AscendC::PipeBarrier<PIPE_V>();
123	            CastFromF16ToI8(z_local[rid * num_last_dim], x_local[rid * num_last_dim], quant_min, num_last_dim);
124	        }
125	
126	        z_que.EnQue(z_local);
127	        x_que.FreeTensor(x_local);
128	    }
129	
130	    __aicore__ inline void CopyOut(uint64_t proc_id, int32_t size)
131	    {
132	        AscendC::LocalTensor<int8_t> z = z_que.DeQue<int8_t>();
133	        uint64_t offset = proc_id * row_step * num_last_dim; // 单核一次总共做了多少。
134	        DataCopy(z_gm[offset], z, size);
135	        z_que.FreeTensor(z);
136	    }
137	
138	private:
139	    AscendC::TPipe pipe;
140	    AscendC::TQue<AscendC::QuePosition::VECIN, BUFFER_NUM> x_que;
141	    AscendC::TQue<AscendC::QuePosition::VECOUT, BUFFER_NUM> z_que;
142	    AscendC::GlobalTensor<half> x_gm;
143	    AscendC::GlobalTensor<int8_t> z_gm;
144	    float input_scale{0};
145	    int32_t input_offset{0};
146	    uint32_t num_core{0};       // 一共激活多少AICORE
147	    uint32_t num_first_dim{0};  // 输入的列数
148	    uint32_t num_last_dim{0};   // 输入的列数
149	    uint32_t row_work{0};       // 每个AICORE需要计算多少行
150	    uint32_t row_step{0};       // 除最后一次，每次搬入多少行
151	    uint32_t row_tail_{0};      // 最后一次搬入多少行数据
152	    uint64_t gm_offset_{0};     // GM数据起始位置偏移量
153	    uint32_t nl_first_dim_per_core{0};
154	    uint32_t l_first_dim_per_core{0};
155	    uint32_t first_dim_per_times{0};
156	    half quant_min = -128;
157	};
158	
